      'ใบเสนอราคาร่วมที่ปิดไปก่อนมีระบบนี้ ถ้าบริษัทยังขึ้น “ยังไม่มีผล” ให้กด “เปิดงานอีกครั้ง” ที่แถบหัวในแท็บ “ปิดงาน” แล้วปิดงานใหม่ครั้งเดียว',
