      'ค้นหาชื่อบริษัท หรือดูมุมมองด่วน เช่น ค้างติดตาม แถบใบเสนอราคาร่วมยังแสดงเหนือบริษัทนั้นให้รู้ว่าอยู่ในใบไหน ถ้าใบเสนอราคาร่วมเองไม่ตรงตัวกรอง ยอดของแถบเป็นสีเทาพร้อมคำว่า “ไม่นับในมุมมองนี้” ตรงกับยอดของหมวดและ KPI',
      'ยังไม่มีไฟล์ก็สร้างได้ ใส่เลขที่ ลงวันที่ และยอดรวมเอง ยอดรวมเป็น Forecast แบบพิมพ์เอง และขั้น QUOTATION ของใบเสนอราคาร่วมบันทึกเลขที่ไว้ (ค้นหาด้วยเลขที่ได้) แนบไฟล์ทีหลังที่การ์ดใบเสนอราคาในหน้ารายละเอียด ยอดในไฟล์ใช้แทนยอดที่พิมพ์',
      'บริษัทในใบเสนอราคาร่วมอยู่ปีเดียวกัน ย้ายปีของบริษัทหนึ่ง บริษัทนั้นออกจากใบเสนอราคาร่วม (ระบบถามก่อน) ย้ายปีของใบเสนอราคาร่วม ทุกบริษัทย้ายตามไปด้วย',
      'Cashflow แสดงเงินของใบเสนอราคาร่วมเป็นรายการเดียวของผู้จ่าย พร้อมจำนวนบริษัท',
      'บริษัทที่เพิ่มเป็นแถวใหม่ได้ Services ของใบเสนอราคาร่วม จึงนับในกราฟ Services และตัวกรอง Services เป็นรายบริษัท',
